import numpy as np


def q547(events):
    clean = events.sort_values("version", kind="stable").drop_duplicates(
        "event_id", keep="last"
    )
    result = (
        clean.groupby(["node", "band", "quarter"], dropna=False)[
            ["sessions", "purchases"]
        ]
        .sum()
        .reset_index()
    )
    result["conversion"] = result["purchases"] / result["sessions"].replace(
        0, np.nan
    )
    return (
        result,
        {
            "input": len(events),
            "deduplicated": len(clean),
            "groups": len(result),
        },
    )
